import CrudCatalog from '../../components/CrudCatalog.vue';
import ApiTestParameterDialog from '../../components/ApiTestParameterDialog.vue';
import CategoryCardPager from '../../components/CategoryCardPager.vue';
import { apiServicesApi as api, assetsApi } from '../../services/api';
import { buildTestNotification } from '../../utils/test-result';
import '../../styles/views/database-mcp.css';

const objectSchema = {
  type: 'object',
  properties: {},
  required: [],
  additionalProperties: false
};

export default {
  name: 'ApiServicesView',
  components: { CrudCatalog, ApiTestParameterDialog, CategoryCardPager },
  emits: ['notify', 'error', 'result'],
  data() {
    return {
      api,
      busy: false,
      activeTab: 'services',
      categories: [],
      allServices: [],
      selectedCategory: '',
      gatewayAssets: [],
      livedataApis: [],
      livedataKeyword: '',
      livedataStatus: '',
      livedataPage: 1,
      livedataPageSize: 20,
      selectedLivedata: new Set(),
      overwriteExisting: false,
      livedataConfig: null,
      livedataSqlAssets: [],
      livedataDatasourceDialogOpen: false,
      selectedLivedataDatasourceId: '',
      selectedLivedataGatewayId: '',
      defaults: {
        enabled: true,
        cacheEnabled: false,
        cacheTtlSeconds: 300,
        inputSchema: objectSchema,
        outputSchema: objectSchema,
        capabilitySpec: {},
        dependencySpec: {},
        governance: {},
        categoryId: ''
      },
      enabledListFilters: [
        {
          key: 'enabled',
          label: '启用状态',
          placeholder: '全部状态',
          options: boolOptions()
        }
      ],
      searchableFields: ['toolName', 'title', 'description', 'businessGroup', 'businessGroupName', 'urlTemplate'],
      columns: [
        { key: 'toolName', label: '工具名称', type: 'code' },
        { key: 'title', label: '显示名称' },
        { key: 'businessGroupName', label: '业务分类' },
        { key: 'gatewayId', label: '网关资产', formatter: value => value || '-' },
        { key: 'enabled', label: '状态', type: 'badge', formatter: value => value === false ? '停用' : '启用' }
      ]
    };
  },
  computed: {
    formFields() {
      return [
        {
          key: 'toolName',
          label: '工具名称',
          required: true,
          placeholder: '如 weather_api',
          help: 'API 服务工具名沿用 <业务能力>_api 命名，例如 weather_api、customer_profile_api；只使用小写字母、数字和下划线，保存后避免随意修改。',
          section: 'basic',
          sectionTitle: '基础信息',
          sectionSubtitle: '定义 API 服务发布成 MCP 工具后的名称和展示信息。'
        },
        {
          key: 'title',
          label: '显示名称',
          required: true,
          placeholder: '如 查询客户画像',
          help: '面向业务用户展示的名称，尽量说明接口能查询或执行的业务能力。',
          section: 'basic'
        },
        {
          key: 'gatewayId',
          label: 'API 网关资产',
          type: 'select',
          required: true,
          span: 'col-12',
          options: this.gatewayOptions,
          placeholder: '选择已维护并测试通过的 API 网关资产',
          help: 'HTTP 方法、URL、Header 和 Body 模板在网关资产中维护；这里只关联已有网关资产。',
          section: 'basic'
        },
        {
          key: 'description',
          label: '工具描述',
          type: 'textarea',
          span: 'col-12',
          placeholder: '说明接口用途、输入参数含义、返回数据范围和适用场景。',
          help: '描述会参与工具检索，建议包含业务对象、关键词和调用限制。',
          section: 'basic'
        },
        {
          key: 'inputSchema',
          label: '请求参数',
          type: 'jsonSchema',
          defaultValue: objectSchema,
          span: 'col-12',
          namePlaceholder: '如 customerId',
          descriptionPlaceholder: '说明参数格式、来源或枚举范围',
          emptyText: '暂无请求参数。需要模型传参时点击“新增参数”。',
          help: '配置模型调用该 API 服务时需要传入的业务参数；参数名应和网关资产的 URL/Body 占位符保持一致。',
          section: 'request',
          sectionTitle: '请求参数',
          sectionSubtitle: '维护模型需要传入的业务参数，保存时自动生成 JSON Schema。'
        },
        {
          key: 'categoryId',
          label: '业务分类',
          type: 'select',
          required: true,
          options: () => this.categoryOptions,
          placeholder: '选择 API 业务分类',
          help: '模板检索会先按该分类缩小候选集，再在分类内进行语义排序。',
          section: 'group',
          sectionTitle: '业务分类',
          sectionSubtitle: '分类是模板检索的强边界，可避免不同业务接口相互干扰。'
        },
        {
          key: 'outputSchema',
          label: '返回字段',
          type: 'jsonSchema',
          defaultValue: objectSchema,
          span: 'col-12',
          namePlaceholder: '如 customerId、riskLevel',
          descriptionPlaceholder: '说明返回字段的业务含义和单位',
          emptyText: '暂无返回字段。需求覆盖分析需要返回字段时点击“新增参数”。',
          help: '用于判断 API 是否能提供需求需要的数据，不会作为请求参数发送。',
          section: 'capability',
          sectionTitle: '能力与结果',
          sectionSubtitle: '以可视化方式描述 API 能做什么、返回什么以及依赖哪些前置能力。'
        },
        {
          key: 'capabilitySpec',
          label: '能力说明',
          type: 'jsonObject',
          span: 'col-12',
          keyPlaceholder: '如 businessObject、operation、intentAliases',
          valuePlaceholder: '如 客户、查询画像、客户信息/客户画像',
          emptyText: '暂无能力标签，点击“新增键值”配置。',
          help: '建议维护业务对象、操作、适用场景和意图别名；这些内容参与 API 能力检索。',
          section: 'capability'
        },
        {
          key: 'dependencySpec',
          label: '依赖说明',
          type: 'jsonObject',
          span: 'col-12',
          keyPlaceholder: '如 dependsOn、preconditions、parameterSources',
          valuePlaceholder: '如 customer_profile_api 或 需先取得 customerId',
          emptyText: '无前置依赖时可以留空。',
          help: '描述前置 API、调用条件和参数来源，用于生成多 API 执行 DAG。',
          section: 'capability'
        },
        {
          key: 'enabled',
          label: '启用',
          type: 'select',
          required: true,
          options: boolOptions(),
          help: '停用后不会作为 MCP 工具发布。',
          section: 'runtime',
          sectionTitle: '运行策略',
          sectionSubtitle: '控制发布状态和查询缓存策略。'
        },
        {
          key: 'cacheEnabled',
          label: '查询缓存',
          type: 'select',
          required: true,
          options: boolOptions(),
          help: '适合只读查询接口；会按请求参数缓存结果。',
          section: 'runtime'
        },
        {
          key: 'cacheTtlSeconds',
          label: '缓存有效期（秒）',
          type: 'number',
          required: form => form.cacheEnabled === true,
          min: 1,
          step: 1,
          placeholder: '300',
          help: '缓存开启时生效，单位秒。',
          section: 'runtime'
        }
      ];
    },
    gatewayOptions() {
      const options = [];
      this.gatewayAssets.forEach(asset => {
        options.push({
          value: asset.id,
          label: [asset.name || asset.title || asset.toolName || asset.id, asset.environment, asset.method].filter(Boolean).join(' / ')
        });
      });
      return options;
    },
    categoryOptions() {
      return this.categories
        .filter(item => item.enabled !== false)
        .map(item => ({ value: item.id, label: `${item.name} / ${item.code}` }));
    },
    categoryCards() {
      return [
        { id: '', code: '', name: '全部服务', description: '查看全部 API 服务', count: this.allServices.length },
        ...this.categories.filter(item => item.enabled !== false).map(item => ({
          ...item,
          count: this.allServices.filter(service =>
            service.categoryId === item.id || service.businessGroup === item.code).length
        }))
      ];
    },
    filteredLivedata() {
      const keyword = this.livedataKeyword.toLowerCase();
      return this.livedataApis.filter(item => {
        const status = item.registered ? 'registered' : (item.canRegister ? 'available' : 'unavailable');
        if (this.livedataStatus && status !== this.livedataStatus) return false;
        if (!keyword) return true;
        return [
          'name', 'apiName', 'apiId', 'title', 'toolName', 'serviceName', 'methodName', 'namespace'
        ].some(key => String(item[key] || '').toLowerCase().includes(keyword));
      });
    },
    paginatedLivedata() {
      const maxPage = Math.max(1, Math.ceil(this.filteredLivedata.length / this.livedataPageSize));
      const page = Math.min(this.livedataPage, maxPage);
      const start = (page - 1) * this.livedataPageSize;
      return this.filteredLivedata.slice(start, start + this.livedataPageSize);
    },
    currentLivedataPageSelectableIds() {
      return this.paginatedLivedata
        .filter(item => item.canRegister)
        .map(item => item.id);
    },
    isCurrentLivedataPageSelected() {
      return this.currentLivedataPageSelectableIds.length > 0
        && this.currentLivedataPageSelectableIds.every(id => this.selectedLivedata.has(id));
    },
    isCurrentLivedataPageIndeterminate() {
      const selectedCount = this.currentLivedataPageSelectableIds
        .filter(id => this.selectedLivedata.has(id)).length;
      return selectedCount > 0 && selectedCount < this.currentLivedataPageSelectableIds.length;
    },
    livedataDatasourceOptions() {
      return this.livedataSqlAssets
        .filter(asset => asset.enabled !== false)
        .map(asset => ({
          value: asset.id,
          label: [asset.name || asset.title || asset.toolName || asset.id, asset.environment, asset.databaseType]
            .filter(Boolean)
            .join(' / ')
        }));
    },
    livedataGatewayOptions() {
      return this.gatewayAssets
        .filter(asset => asset.enabled !== false)
        .map(asset => ({
          value: asset.id,
          label: [asset.name || asset.title || asset.toolName || asset.id, asset.environment, asset.urlTemplate]
            .filter(Boolean)
            .join(' / ')
        }));
    }
  },
  watch: {
    livedataKeyword() {
      this.livedataPage = 1;
    },
    livedataStatus() {
      this.livedataPage = 1;
    }
  },
  mounted() {
    this.loadGatewayAssets();
    this.loadCategories();
  },
  methods: {
    async loadCategories() {
      try {
        const [categories, services] = await Promise.all([api.listCategories(), api.list()]);
        this.categories = categories || [];
        this.allServices = services || [];
      } catch (error) {
        this.$emit('error', error);
      }
    },
    async listServices() {
      const services = await api.list() || [];
      this.allServices = services;
      if (!this.selectedCategory) return services;
      return services.filter(service => service.categoryId === this.selectedCategory
        || service.businessGroup === this.selectedCategory);
    },
    async selectCategory(category) {
      this.selectedCategory = category.id || category.code || '';
      this.activeTab = 'services';
      await this.$nextTick();
      await this.$refs.catalog?.load?.();
    },
    async loadGatewayAssets() {
      try {
        this.gatewayAssets = await assetsApi.listHttp() || [];
      } catch (error) {
        this.$emit('error', error);
      }
    },
    async testService(item, args) {
      return api.test(item.id, args);
    },
    async loadLivedata() {
      this.busy = true;
      try {
        const [config, sqlAssets, gatewayAssets] = await Promise.all([
          api.getLivedataConfig(),
          assetsApi.listSql(),
          assetsApi.listHttp()
        ]);
        if (!config?.enabled) {
          throw new Error('LiveData 后台未启用，请先启用 LiveData 配置。');
        }
        this.livedataConfig = config;
        this.livedataSqlAssets = sqlAssets || [];
        this.gatewayAssets = gatewayAssets || [];
        const configuredAssetExists = this.livedataSqlAssets.some(asset =>
          asset.enabled !== false && asset.id === config.datasourceId
        );
        this.selectedLivedataDatasourceId = configuredAssetExists ? config.datasourceId : '';
        const configuredGatewayExists = this.gatewayAssets.some(asset =>
          asset.enabled !== false && asset.id === config.gatewayId
        );
        this.selectedLivedataGatewayId = configuredGatewayExists ? config.gatewayId : '';
        this.livedataDatasourceDialogOpen = true;
      } catch (error) {
        this.$emit('error', error);
      } finally {
        this.busy = false;
      }
    },
    async confirmLivedataDatasource() {
      if (!this.selectedLivedataDatasourceId || !this.selectedLivedataGatewayId || !this.livedataConfig) return;
      this.busy = true;
      try {
        this.livedataConfig = await api.saveLivedataConfig({
          ...this.livedataConfig,
          datasourceId: this.selectedLivedataDatasourceId,
          gatewayId: this.selectedLivedataGatewayId
        });
        this.livedataApis = await api.listLivedata() || [];
        this.livedataPage = 1;
        this.selectedLivedata = new Set();
        this.livedataDatasourceDialogOpen = false;
        this.$emit('notify', {
          title: 'LiveData API 加载成功',
          message: `已加载 ${this.livedataApis.length} 个可注册 API`
        });
      } catch (error) {
        this.$emit('error', error);
      } finally {
        this.busy = false;
      }
    },
    toggleLivedata(id) {
      const next = new Set(this.selectedLivedata);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      this.selectedLivedata = next;
    },
    toggleCurrentLivedataPage(checked) {
      const next = new Set(this.selectedLivedata);
      this.currentLivedataPageSelectableIds.forEach(id => {
        if (checked) next.add(id);
        else next.delete(id);
      });
      this.selectedLivedata = next;
    },
    changeLivedataPageSize(size) {
      this.livedataPageSize = size;
      this.livedataPage = 1;
    },
    async registerSelected() {
      this.busy = true;
      try {
        const requested = this.selectedLivedata.size;
        const result = await api.registerLivedata([...this.selectedLivedata], this.overwriteExisting);
        if (!result?.registered) {
          const details = result?.errors?.length ? `：${result.errors.join('；')}` : '';
          throw new Error(`没有 API 注册成功，跳过 ${result?.skipped || 0} 个，未找到 ${result?.missing || 0} 个${details}`);
        }
        this.$emit('notify', {
          title: '注册成功',
          message: `提交 ${requested} 个，成功 ${result.registered} 个，跳过 ${result.skipped || 0} 个，未找到 ${result.missing || 0} 个`
        });
        if (result.errors?.length) {
          this.$emit('result', { title: '部分 LiveData API 注册失败', value: result });
        }
        this.selectedLivedata = new Set();
        this.livedataApis = await api.listLivedata() || [];
        this.activeTab = 'services';
        await this.$nextTick();
        this.$refs.catalog.keyword = '';
        this.$refs.catalog.page = 1;
        await this.$refs.catalog.load();
      } catch (error) {
        this.$emit('error', error);
      } finally {
        this.busy = false;
      }
    },
    async syncLivedataParameters() {
      this.busy = true;
      try {
        const result = await api.syncLivedataParameters();
        await this.loadCategories();
        await this.$refs.catalog?.load?.();
        this.$emit('notify', {
          title: 'API 参数同步完成',
          message: `匹配 ${result?.matched || 0} 个，更新 ${result?.updated || 0} 个，未变化 ${result?.unchanged || 0} 个`
        });
        if (result?.errors?.length) {
          this.$emit('result', { title: '部分 API 参数同步失败', value: result });
        }
      } catch (error) {
        this.$emit('error', error);
      } finally {
        this.busy = false;
      }
    },
    async testLivedata(row) {
      try {
        const args = await this.$refs.apiTestParameterDialog.open({
          title: `${row.apiName || row.title || row.toolName || 'LiveData API'} 请求测试`,
          schema: row.inputSchemaJson
        });
        this.busy = true;
        const result = await api.testLivedata(row.id, args);
        this.$emit('notify', buildTestNotification(result));
        this.$emit('result', {
          title: `${row.apiName || row.title || row.toolName || 'LiveData API'} 请求测试结果`,
          value: result
        });
      } catch (error) {
        if (error !== 'cancel' && error !== 'close') this.$emit('error', error);
      } finally {
        this.busy = false;
      }
    }
  }
};

function boolOptions() {
  return [{ value: true, label: '启用' }, { value: false, label: '停用' }];
}
